local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = require('XLua.cs_coroutine')
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local KCookie = CS.Engine.Lib.KCookie

---@type EquipQuestComponent
local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
local CriWareUtils =  import('Game.Entry.CriWareUtilsFix')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

---@class UIDisasterResponseMapPanel
---@field Btn                           	UnityEngine.UI.Button
---@field FontStyleButton               	Game.Native.Common.FontStyleButton
---@field Container                     	UnityEngine.RectTransform
---@field ImgBox3                       	UnityEngine.UI.Image
---@field ImgBox2                       	UnityEngine.UI.Image
---@field ImgBox1                       	UnityEngine.UI.Image
---@field ImgRole                       	UnityEngine.UI.RawImage
---@field Txt3                          	TMPro.TextMeshProUGUI
---@field TxtLevel2                     	TMPro.TextMeshProUGUI
---@field TxtLevel1                     	TMPro.TextMeshProUGUI
---@field TxtNumber                     	UnityEngine.UI.Text
local UIDisasterResponseMapPanel = Class("UIDisasterResponseMapPanel")

function UIDisasterResponseMapPanel:__init()
    self._curQuestId = nil               --当前副本id
    self._curQuestVo = nil               --当前副本
end

function UIDisasterResponseMapPanel:__delete()
    self._curQuestVo = nil               --当前副本
    self._curQuestId = nil               --当前副本id
end

function UIDisasterResponseMapPanel:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnFontStyleButton))
end

function UIDisasterResponseMapPanel:Refresh()
    self._curQuestId = equipQuestComp:GetCurSeniorQuestId()

    ---@type QuestSeniorEquipChapterVo
    self._curQuestVo = CfUtils.GetCfVo(AutoIds.IdSetting844, "QuestSeniorEquipChapterVo", self._curQuestId)
    if not self._curQuestVo then
        return
    end

    self:FillSelf()
end

function UIDisasterResponseMapPanel:SetChangeCB(handler)
    self.changeCB = handler
end
function UIDisasterResponseMapPanel:GetChangeCB()
    return self.changeCB
end

function UIDisasterResponseMapPanel:FillSelf()
    CfUtils.FillText(self.TxtNumber, self._curQuestVo.name)
    CfUtils.FillText(self.TxtLevel1, self._curQuestVo.regionLevel < 10 and "0"..self._curQuestVo.regionLevel or self._curQuestVo.regionLevel)
    CfUtils.FillText(self.TxtLevel2, "/10")
    local animNodeIndex = self:FillNodes()

    local point   = equipQuestComp:GetPointAdd()

    if point > 0 and animNodeIndex > 0 then
        equipQuestComp:SetLastSubEquipPassedQuestId(0)
        CfUtils.FillText(self.Txt3, checkInt(self.Txt3.text) - point)

        self.animCo = cs_coroutine.start(function()
            local centerNodeTime = CfUtils.GetAnimatorTime(self.Container:Find("CenterGroup"), "UIFastReliefDisasterResponseMapDialogCenterGroupOpen")
            cs_coroutine.yield_return(WaitForSeconds(centerNodeTime))

            local go         = self.Container:Find("Btn" .. animNodeIndex)
            local animNode   = go:Find("AnimRoot")
            local parentNode = animNode:Find("FXPoint")

            if not KTool.IsNull(parentNode) then
                CfUtils.PlayAnimator(animNode.gameObject, "Change")

                local prefabPath = "Effect/prefab/ui_prefab/UIFX_FastReliefDisasterResponseMapDialogBoom.prefab"
                GameUtils.LoadBundleSync(prefabPath, parentNode, nil, true)
                self:UpdateQuestNodePassState(go, true)

                local flyPrefabPath = "Effect/prefab/ui_prefab/UIFX_FastReliefDisasterResponseMapDialogMove.prefab"
                local flyPrefabNode = GameUtils.LoadBundleAsync(flyPrefabPath, parentNode, nil, true)
                local animNode = self.Container:Find("GroupBG")
                if not KTool.IsNull(animNode) then
                    local imgBg = animNode:Find("ImgBg").gameObject
                    if not KTool.IsNull(imgBg) then
                        flyPrefabNode.transform:DOMove(imgBg.transform.position, 0.66)

                        cs_coroutine.yield_return(WaitForSeconds(0.66))
                        KTool.SafeDelete(flyPrefabNode)

                        local prefabPath  = "Effect/prefab/ui_prefab/UIFX_FastReliefDisasterResponseMapDialogBoom2.prefab"
                        local fxPointNode = animNode:Find("FXPoint").gameObject
                        if not KTool.IsNull(fxPointNode) then
                            GameUtils.LoadBundleSync(prefabPath, fxPointNode, nil, true)
                        end
                        CfUtils.PlayAnimator(animNode, "Up")
                    end
                end
                cs_coroutine.yield_return(WaitForSeconds(0.5))
                CfUtils.FillText(self.Txt3, checkInt(self.Txt3.text) + point)
            else
                self:UpdateQuestNodePassState(go, true)
                CfUtils.FillText(self.Txt3, checkInt(self.Txt3.text) + point)
            end

            self.animCo = nil
        end)
    end
end

function UIDisasterResponseMapPanel:FillNodes()
    local totalCost = tonumber(self._curQuestVo.initialCost)
    local nodes = CfUtils.Split(self._curQuestVo.pointID)
    local animNodeIndex = 0

    local nodeIdx = 1
    for i = 1, 7 do
        local questId = checkInt(nodes[i])
        local go      = self.Container:Find("Btn" .. nodeIdx)
        KTool.SetActive(go.gameObject, questId > 0)
        if questId > 0 then
            ---@type QuestSeniorEquipVo
            local questVo = CfUtils.GetCfVo(AutoIds.IdSetting848, "QuestSeniorEquipVo", questId)
            ---@type QuestSeniorEquipBattleTypeVo
            local typeVo = CfUtils.GetCfVo(AutoIds.IdSetting843, "QuestSeniorEquipBattleTypeVo", questVo.pointType)

            if equipQuestComp:GetLastSubEquipPassedQuestId() > 0 and equipQuestComp:GetLastSubEquipPassedQuestId() == questId then
                animNodeIndex = nodeIdx
            end

            if typeVo.id == 2 then
                CfUtils.FillImage(self.ImgRole, QuestConfMgr:GetInstance():GetMonsterHeadIcon(questVo), true)
                local rewardList = string.split(self._curQuestVo.showReward, ";")
                for index = 1, 3 do
                    CfUtils.FillImage(self["ImgBox" .. index], GoodsConfMgr:GetPhotoPathById(rewardList[index]))
                end

                SetButtonAction(self.Btn, function()
                    if not isPass then
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = questId, isThreeTripleMode = equipQuestComp:IsThreeTripleMode()}}, {
                            {id = Constants.UITypeIds.UIFastReliefDisasterResponseDialog}
                        })
                    end
                end)

                local pos    = CfUtils.Split(questVo.location)
                if pos then
                    self.Container:Find("CenterGroup").localPosition = Vector3(checkNumber(pos[1]), checkNumber(pos[2]), 0)
                end
            else
                self:RefreshCellNode(go, questId, animNodeIndex == nodeIdx)
                if QuestConfMgr:GetInstance():IsPassQuest(questId) then
                    totalCost = totalCost + tonumber(typeVo.rewardCost)
                end
                nodeIdx = nodeIdx + 1
            end
        else
            nodeIdx = nodeIdx + 1
        end
    end
    CfUtils.FillText(self.Txt3, totalCost)
    return animNodeIndex
end

function UIDisasterResponseMapPanel:RefreshCellNode(go, questId, isNeedAnim)
    ---@type QuestSeniorEquipVo
    local questVo = CfUtils.GetCfVo(AutoIds.IdSetting848, "QuestSeniorEquipVo", questId)
    ---@type QuestSeniorEquipBattleTypeVo
    local typeVo = CfUtils.GetCfVo(AutoIds.IdSetting843, "QuestSeniorEquipBattleTypeVo", questVo.pointType)
    local isPass   = QuestConfMgr:GetInstance():IsPassQuest(questId)

    local animRoot = go:Find("AnimRoot")
    CfUtils.FillText(animRoot:Find("ImgIcon1"):Find("TxtNumber"), string.format("+%s", typeVo.rewardCost))
    self:UpdateQuestNodePassState(go, isPass and not isNeedAnim)

    local pos    = CfUtils.Split(questVo.location)
    if pos then
        go.localPosition = Vector3(checkNumber(pos[1]), checkNumber(pos[2]), 0)
    end

    SetButtonAction(go, function()
        if not isPass then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = questId, isThreeTripleMode = equipQuestComp:IsThreeTripleMode()}}, {
                {id = Constants.UITypeIds.UIFastReliefDisasterResponseDialog}
            })
        end

    end)
end

function UIDisasterResponseMapPanel:UpdateQuestNodePassState(go, isPass)
    local animRoot = go:Find("AnimRoot")
    local imgBg    = animRoot:Find("ImgBg")
    CfUtils.SetUISwitchImage(imgBg, isPass and 2 or 1)
    local norImgNode = animRoot:Find("ImgIcon1")
    KTool.SetActive(norImgNode, not isPass)
    local passImgNode = animRoot:Find("ImgIcon2")
    KTool.SetActive(passImgNode, isPass)
end

function UIDisasterResponseMapPanel:OnFontStyleButton()
    equipQuestComp:GiveUpQuestReq(function()
        KCookie.Set("UIDisasterResponseDialogOpenAnimName", "Open2")
        if self:GetChangeCB() ~= nil then
            self:GetChangeCB()()
        end
    end)
end

function UIDisasterResponseMapPanel:OnDestroy()
    if self.animCo then
        cs_coroutine.stop(self.animCo)
        self.animCo = nil
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return UIDisasterResponseMapPanel
